chapter(13, 'Tariff, yield and the tariff card', 'Read the rate calendar and the pricing rules, send a rate change for approval, approve it as Owner, and prepare and print a tariff card.',
        'Meera (Manager)', 'manager', menu='Revenue & Sales > Tariff & yield')
step('Meera, the Manager, is on Modules Home. Prices are set in the Revenue & Sales module.', 'The manager proposes price changes; the Owner decides.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:manager'], action='read', expect='Modules Home for Meera.', check="ctx.uid==='manager'")
tile('Revenue & Sales', 'Click the Revenue & Sales tile.', 'Tariff, groups, OTA, the booking site and the halls are here.', expect='The Revenue & Sales page opens.')
leaf('Revenue & Sales', 'Tariff & yield', 'Click the Tariff & yield tile.', 'It shows the live rate and the rate HCC suggests for every night.', expect='Tariff & yield opens on the Rate calendar.', check="ctx.page==='yield'")
read('The Rate calendar lists each room type and night with the suggested rate and the live rate. For Classic on Saturday 31 Oct HCC suggests Rs 2,400 while the live rate is still Rs 2,000.', 'Suggestions come from the season, the day of the week and how full the hotel is; nothing changes until a publish is approved.',
     target='sel:main h1', expect='The rate calendar.')
click('tab:Rate plans', 'Open the Rate plans tab.', 'It holds the rate sheet and a calculator that quotes a stay.', expect='The rate sheet and the quote form open.')
click('tab:Rules', 'Open the Rules tab.', 'Seasons, days of the week, occupancy tiers and guardrails are the rules behind the suggestions; the guardrails stop a rate going too low or too high.', expect='The rules are listed.')
click('tab:Restrictions', 'Open the Restrictions tab.', 'A restriction, such as a minimum stay on a festival weekend, protects the best nights.', expect='The stay restrictions are listed.')
click('tab:History', 'Open the History tab.', 'Every published change is kept with its reason and who approved it.', expect='The history of rate changes opens.')
click('btn:Propose publish', 'Click Propose publish to send the suggested rates for approval.', 'A manager cannot change the live price alone.', expect='The Propose a tariff publish dialog opens.', check="has('Send for approval')")
read('Choose the first and last night and the room types, and give a reason that is kept in the history and shown to the approver.', 'A clear reason makes the Owner\'s decision quick.', target='dialog:', expect='The propose form.')
typ('field:Reason', 'Weekend uplift for the festival days', 'Type the reason: Weekend uplift for the festival days.', 'The reason is shown to the Owner.', expect='Reason filled.')
click('modalbtn:Send for approval', 'Click Send for approval.', 'The request waits for the Owner; the live rates stay as they are.', expect='The request is sent.')
step('Sagar, the Owner, opens Tariff & yield. A new tab, Publish requests, shows the request. Open it.', 'Only the Owner publishes prices.', target='tab:Publish requests', auto=['user:owner', 'click:menutop:Revenue & Sales', 'click:menuleaf:Tariff & yield', 'click:tab:Publish requests'], action='click',
     expect='The publish request is listed with Approve & publish and Reject.', check="has('Approve & publish')")
click('btn:Approve & publish', 'Click Approve & publish.', 'From that night on the new rates are live for new bookings; existing bookings keep their agreed rate.', expect='The new rates are published.')
step('Now the tariff card. Back as Meera, open Tariff card under Revenue & Sales and click New draft.', 'The tariff card is the printed price list of rooms, meal plans, extras and halls, valid from a date.', target='btn:Propose',
     auto=['user:manager', 'click:menutop:Revenue & Sales', 'click:menuleaf:Tariff card', 'click:btn:New draft'], action='click', expect='A draft card TRC-0001 opens with every price including GST.', check="has('TRC-0001')")
read('The draft lists every room type, extra person, extra bed, meal plan and hall with the price including GST. The tabs Rooms, Meal plans & extras, Seasons & weekends and Halls hold the groups.', 'Guests ask for the card at the desk; it must always match the live prices.', target='sel:main h2', expect='The draft tariff card.')
click('tab:Seasons', 'Open the Seasons & weekends tab.', 'Season uplifts are printed on the card so that guests know the weekend rate.', expect='The season prices are listed.')
read('The Propose button sends the draft to the Owner, who publishes it. The training does not send it, because a card with the same start date as the rates just published would be refused.', 'Two price lists for the same date would confuse the desk, so HCC refuses the second.', target='btn:Propose', expect='The draft stays a draft.')
click('tab:Print', 'Open the Print tab.', 'The card prints on one page with the hotel name and the valid-from date; printing never changes a price.', expect='The print preview of the tariff card opens.')
